/// </summary>
class METPOConfirmationPostMultiThreadTask extends RunBaseBatch
{
    // Packed variables
    container companyAndPurchId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        companyAndPurchId
    #endmacro
   
}

Method.Source:
/// <summary>
/// Contains the code that does the actual job of the class.
/// </summary>
public void run()
{
    #OCCRetryCount        
    DataAreaId  company;
    PurchId     purchId;
    str         companyAndPurchIdStr;               
    
    companyAndPurchIdStr        = conPeek(companyAndPurchId,1);
    company                     = subStr(companyAndPurchIdStr,1,strFind(companyAndPurchIdStr,METConstants::colon,1,strLen(companyAndPurchIdStr))-1);
    purchId                     = subStr(companyAndPurchIdStr,strFind(companyAndPurchIdStr,METConstants::colon,1,strLen(companyAndPurchIdStr))+1,strLen(companyAndPurchIdStr));
        
    METPOConfirmationPost   metPOConfirmationPost = new METPOConfirmationPost();
    metPOConfirmationPost.postConfirmation(company,purchId);
                   
}

    public boolean unpack(container packedClass)
    {
        Version version = RunBase::getVersion(packedClass);
        ;
        switch (version)
        {
            case #CurrentVersion:
                [version,#CurrentList] = packedClass;
                break;
            default:
                return false;
        }

        return true;
    }

